"use client";

import { useEffect, useState } from "react";
import Header from "@/components/common/Header";
import Navbar from "@/components/common/Navbar";
import Footer from "@/components/common/Footer";
import axios from "axios";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL;

// Definisi tipe data Warehouse
interface Warehouse {
  id: number;
  name: string;
  address: string;
  longitude: string;
  latitude: string;
  cityId: number;
}

// Definisi tipe data untuk assign admin
interface AdminAssignment {
  warehouseId: number;
  adminEmail: string;
}

const WarehousePage = () => {
  const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [newWarehouse, setNewWarehouse] = useState<Omit<Warehouse, "id">>({
    name: "",
    address: "",
    longitude: "",
    latitude: "",
    cityId: 0,
  });

  const [editWarehouse, setEditWarehouse] = useState<Warehouse | null>(null);
  const [adminAssignment, setAdminAssignment] = useState<AdminAssignment>({
    warehouseId: 0,
    adminEmail: "",
  });

  useEffect(() => {
    fetchWarehouses();
  }, []);

  const fetchWarehouses = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get<Warehouse[]>(`${BACKEND_URL}/api/v1/warehouse`);
      setWarehouses(response.data);
    } catch (err) {
      setError("Failed to fetch warehouses");
    } finally {
      setLoading(false);
    }
  };

  const createWarehouse = async () => {
    try {
      await axios.post(`${BACKEND_URL}/api/v1/warehouse`, newWarehouse);
      setNewWarehouse({ name: "", address: "", longitude: "", latitude: "", cityId: 0 });
      fetchWarehouses();
    } catch (err) {
      console.error("Failed to create warehouse", err);
    }
  };

  const updateWarehouse = async () => {
    if (!editWarehouse) return;
    try {
      await axios.put(`${BACKEND_URL}/api/v1/warehouse/${editWarehouse.id}`, editWarehouse);
      setEditWarehouse(null);
      fetchWarehouses();
    } catch (err) {
      console.error("Failed to update warehouse", err);
    }
  };

  const deleteWarehouse = async (warehouseId: number) => {
    try {
      await axios.delete(`${BACKEND_URL}/api/v1/warehouse/${warehouseId}`);
      fetchWarehouses();
    } catch (err) {
      console.error("Failed to delete warehouse", err);
    }
  };

  const assignAdmin = async () => {
    try {
      await axios.post(`${BACKEND_URL}/api/v1/warehouse/${adminAssignment.warehouseId}/assign-admin`, {
        email: adminAssignment.adminEmail,
      });
      setAdminAssignment({ warehouseId: 0, adminEmail: "" });
      alert("Admin assigned successfully!");
    } catch (err) {
      console.error("Failed to assign admin", err);
    }
  };

  return (
    <div className="flex min-h-screen flex-col bg-gray-100 text-black">
      <Header />
      <Navbar />
      <div className="flex-grow p-6 bg-white shadow-md">
        <h1 className="text-2xl font-bold mb-4">🏭 Warehouses</h1>

        {error && <div className="text-red-500 mb-4">{error}</div>}

        {/* Add Warehouse */}
        <div className="mb-4">
          <h2 className="text-lg font-semibold">➕ Add Warehouse</h2>
          <input
            type="text"
            placeholder="Warehouse Name"
            className="border p-2 mr-2"
            value={newWarehouse.name}
            onChange={(e) => setNewWarehouse({ ...newWarehouse, name: e.target.value })}
          />
          <input
            type="text"
            placeholder="Address"
            className="border p-2 mr-2"
            value={newWarehouse.address}
            onChange={(e) => setNewWarehouse({ ...newWarehouse, address: e.target.value })}
          />
          <input
            type="text"
            placeholder="Longitude"
            className="border p-2 mr-2"
            value={newWarehouse.longitude}
            onChange={(e) => setNewWarehouse({ ...newWarehouse, longitude: e.target.value })}
          />
          <input
            type="text"
            placeholder="Latitude"
            className="border p-2 mr-2"
            value={newWarehouse.latitude}
            onChange={(e) => setNewWarehouse({ ...newWarehouse, latitude: e.target.value })}
          />
          <input
            type="number"
            placeholder="City ID"
            className="border p-2 mr-2"
            value={newWarehouse.cityId}
            onChange={(e) => setNewWarehouse({ ...newWarehouse, cityId: Number(e.target.value) })}
          />
          <button className="bg-green-500 text-white px-4 py-2" onClick={createWarehouse}>
            Add Warehouse
          </button>
        </div>

        {/* Update Warehouse */}
        {editWarehouse && (
          <div className="mb-4">
            <h2 className="text-lg font-semibold">✏️ Edit Warehouse</h2>
            <input
              type="text"
              className="border p-2 mr-2"
              value={editWarehouse.name}
              onChange={(e) => setEditWarehouse({ ...editWarehouse, name: e.target.value })}
            />
            <button className="bg-blue-500 text-white px-4 py-2" onClick={updateWarehouse}>
              Save Changes
            </button>
            <button className="bg-gray-500 text-white px-4 py-2 ml-2" onClick={() => setEditWarehouse(null)}>
              Cancel
            </button>
          </div>
        )}

        {/* Assign Admin */}
        <div className="mb-4">
          <h2 className="text-lg font-semibold">👤 Assign Admin</h2>
          <input
            type="number"
            placeholder="Warehouse ID"
            className="border p-2 mr-2"
            value={adminAssignment.warehouseId}
            onChange={(e) => setAdminAssignment({ ...adminAssignment, warehouseId: Number(e.target.value) })}
          />
          <input
            type="email"
            placeholder="Admin Email"
            className="border p-2 mr-2"
            value={adminAssignment.adminEmail}
            onChange={(e) => setAdminAssignment({ ...adminAssignment, adminEmail: e.target.value })}
          />
          <button className="bg-purple-500 text-white px-4 py-2" onClick={assignAdmin}>
            Assign Admin
          </button>
        </div>

        {/* Warehouse List */}
        {loading ? (
          <p>Loading...</p>
        ) : (
          <ul>
            {warehouses.map((warehouse) => (
              <li key={warehouse.id} className="p-3 bg-white rounded-lg shadow mb-2">
                <h3 className="font-semibold">{warehouse.name}</h3>
                <p>{warehouse.address}</p>
                <button
                  className="bg-yellow-500 text-white px-4 py-2 mt-2 mr-2"
                  onClick={() => setEditWarehouse(warehouse)}
                >
                  Edit
                </button>
                <button
                  className="bg-red-500 text-white px-4 py-2 mt-2"
                  onClick={() => deleteWarehouse(warehouse.id)}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
      <Footer />
    </div>
  );
};

export default WarehousePage;
